customCss:
.wiki-lead { background: linear-gradient(135deg, rgba(138,75,255,0.16), rgba(30,20,50,0.2), rgba(212,168,83,0.1)); padding: 1.5rem; border-left: 6px solid #8a4bff; border-radius: 1rem; margin-bottom: 20px; }
.prose blockquote { background: linear-gradient(135deg, rgba(138,75,255,0.12), rgba(20,20,30,0.15)), var(--bg2); border-left: 4px solid #8a4bff; border-radius: 0 10px 10px 0; padding: 14px 20px; margin: 18px 0; font-size: 14.5px; line-height: 1.8; color: var(--text); }
.prose blockquote strong { color: #d4a853; letter-spacing: 0.03em; }
.prose blockquote em { color: #c9a6ff; font-style: italic; }
.prose h2 { color: #d4a853; border-bottom: 2px solid rgba(212,168,83,0.3); padding-bottom: 6px; font-family: var(--font-title, serif); }
.wnote { background: linear-gradient(135deg, rgba(138,75,255,0.14), rgba(40,20,60,0.1)), var(--bg2); border-left: 4px solid #8a4bff; padding: 14px 18px; margin: 20px 0; border-radius: 0 8px 8px 0; font-size: 13.5px; line-height: 1.65; }
.wnote b { color: #d4a853; font-size: 14px; }
.wnote em { color: #e2c8ff; }
